 "content": "def transform(grid):
    """Extend each bottom-row 5 marker into a vertical color column.

    The nonzero colors already on each marked column are ordered by their
    last occurrence from top to bottom. Each color fills the span after the
    previous color's last occurrence through its own last occurrence.
    """
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        last = {}
        for r in range(h):
            if grid[r][c] != 0:
                last[grid[r][c]] = r
        ordered = sorted(last.items(), key=lambda item: item[1])
        start = 0
        for color, end in ordered:
            for r in range(start, end + 1):
                out[r][c] = color
            start = end + 1
    return out
